add_lead.beforeRequest:
var c = inputs.secondary_contacts ? JSON.parse(inputs.secondary_contacts) : null, n = Math.min(Number(inputs.num_secondary_contacts) || 0, 10), list = [];
if (c && n) for (var i = 1; i <= n; i++) { var p = c['contact_' + i + '_phone']; if (p && p.trim() !== '') list.push({ phone_number: p.trim(), variables: c['contact_' + i + '_variables'] || { customer_name: '' } }); }
if (list.length) request.body.secondary_contacts = list;
return request;

search_available_phone_numbers.beforeRequest:
var c = (inputs.contains || '').trim();
if (/^\d{1,10}$/.test(c)) request.query.contains = c;
return request;

create_campaign.beforeRequest:
['timezone', 'goal_completion_variable'].forEach(function (k) { var v = (inputs[k] || '').trim(); if (v) request.body[k] = v; });
['allowed_days', 'phone_number_ids'].forEach(function (k) { if (Array.isArray(request.body[k]) && !request.body[k].length) delete request.body[k]; });
return request;

update_lead.beforeRequest:
var b = request.body, p = (inputs.phone_number || '').trim(), v = b.variables, hasVariables = v != null && typeof v === 'object' && Object.keys(v).length > 0;
if (!hasVariables) delete b.variables;
if (p) b.phone_number = p;
if (!('campaign_id' in b) && !p && !b.status && !hasVariables) throw new Error('Provide at least one field to update: campaign, phone number, status, or variables.');
return request;

generate_ai_reply.beforeRequest:
var v = request.body.variables, kept = {};
if (v && typeof v === 'object') Object.keys(v).forEach(function (k) { if (v[k] !== '' && v[k] != null) kept[k] = v[k]; });
if (Object.keys(kept).length) request.body.variables = kept; else delete request.body.variables;
return request;

create_conversation.beforeRequest:
var v = request.body.variables, kept = {};
if (v && typeof v === 'object') Object.keys(v).forEach(function (k) { if (v[k] !== '' && v[k] != null) kept[k] = v[k]; });
if (Object.keys(kept).length) request.body.variables = kept; else delete request.body.variables;
return request;

send_whats_app_template.beforeRequest:
var b = request.body, n = (inputs.recipient_name || '').trim();
b.recipient_phone = inputs.recipient_phone.trim();
if (n) b.recipient_name = n;
if (!b.variables || !Object.keys(b.variables).length) delete b.variables;
return request;

send_whats_app_freeform.beforeRequest:
request.body.recipient_phone = inputs.recipient_phone.trim();
request.body.message = inputs.message.trim();
return request;

getAssistants.afterResponse:
let assistants = [], page = 1, answer = response;
while (answer && answer.data && answer.data.length > 0) {
  assistants = assistants.concat(answer.data);
  if (!(page < answer.last_page)) break;
  page++;
  const query = {per_page: String(Number(inputs.per_page) || 10), page: String(page)};
  if (inputs.type) query.type = inputs.type;
  answer = call({method: 'GET', url: '/user/assistants/get', query});
}
return assistants.map(data => ({time: data.updated_at || data.created_at, data}));
